Go to my school calendar, add my test on.text:
{
  "steps": [
    {
      "do": "open",
      "clause": "Go to my school calendar",
      "app": "Calendar"
    },
    {
      "do": "script",
      "clause": "add my test on Friday",
      "app": "Calendar",
      "lang": "applescript",
      "code": "tell application \"Calendar\"\n    activate\n    set theCal to calendar \"School\"\n    set theDate to date \"Friday, November 6, 2026 09:00:00\"\n    make new event at end of events of theCal with properties {summary:\"test\", start date:theDate, end date:theDate + 1 * hours}\nend tell",
      "check": "true"
    },
    {
      "do": "script",
      "clause": "text my mom I'll be late",
      "app": "Messages",
      "lang": "applescript",
      "code": "tell application \"Messages\"\n    activate\n    set targetService to 1st service whose service type = iMessage\n    set targetBuddy to participant \"mom\" of targetService\n    send \"I'll be late\" to targetBuddy\nend tell",
      "check": "true"
    }
  ]
}

