what's on my calendar tomorrow, then tex.text:
{
  "steps": [
    {
      "do": "script",
      "clause": "what's on my calendar tomorrow",
      "app": "Calendar",
      "lang": "applescript",
      "code": "set tomorrowDate to (current date) + days 1\nset dayStart to tomorrowDate - (time of tomorrowDate) + 0 * seconds\nset dayEnd to dayStart + 24 * hours\ntell application \"Calendar\"\n    set theEvents to events where its start date ≥ dayStart and its start date < dayEnd\n    set output to \"\"\n    repeat with ev in theEvents\n        set output to output & (summary of ev) & \": \" & (start date of ev) & \", \" & (location of ev) & linefeed\n    end repeat\n    if output = \"\" then set output to \"No events tomorrow.\"\nend tell\nreturn output",
      "check": "output is not missing value"
    },
    {
      "do": "script",
      "clause": "text Sam I'm running late",
      "app": "WhatsApp",
      "lang": "applescript",
      "code": "tell application \"WhatsApp\"\n    activate\n    delay 0.5\n    set targetContact to \"Sam\"\n    set theMessage to \"I'm running late\"\n    send theMessage to targetContact\nend tell",
      "check": "theMessage was sent"
    }
  ]
}

